/* Dry-run runtime for assembly generated by il2asm.nsis.
 *
 * Each NSIS installer command becomes a call here. Nothing touches the real
 * registry, the real filesystem or the real Start menu: every call records the
 * action and prints it, so a linked installer binary can be inspected to prove
 * that the script was translated statement for statement.
 *
 * Variables live in the generated `.S` (`nsis_var_*`) as `const char *` cells.
 * A command argument can therefore be a literal pointer or a variable cell
 * that was composed at run time with shim_nsis_concat.
 *
 * Build:
 *   gcc -c nsis.c
 */
#include "nsis.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static unsigned long nsis_actions;

static const char *z(const char *s)
{
    return s ? s : "";
}

const char *shim_nsis_concat(const char *a, const char *b)
{
    size_t na = strlen(z(a));
    size_t nb = strlen(z(b));
    char *out = malloc(na + nb + 1);
    if (!out) {
        return "";
    }
    memcpy(out, z(a), na);
    memcpy(out + na, z(b), nb);
    out[na + nb] = '\0';
    return out;
}

int shim_nsis_compare(const char *a, const char *op, const char *b)
{
    const char *lhs = z(a);
    const char *rhs = z(b);
    const char *cmp = z(op);

    if (!strcmp(cmp, "==")) {
        return strcmp(lhs, rhs) == 0;
    }
    if (!strcmp(cmp, "!=")) {
        return strcmp(lhs, rhs) != 0;
    }

    /* LogicLib lowers ordering to IntCmp, so compare numerically. */
    long x = strtol(lhs, NULL, 0);
    long y = strtol(rhs, NULL, 0);
    if (!strcmp(cmp, "<"))  return x <  y;
    if (!strcmp(cmp, ">"))  return x >  y;
    if (!strcmp(cmp, "<=")) return x <= y;
    if (!strcmp(cmp, ">=")) return x >= y;

    fprintf(stderr, "[nsis] unknown comparison %s\n", cmp);
    return 0;
}

static void record(const char *op, const char *a, const char *b,
                   const char *c, const char *d)
{
    ++nsis_actions;
    printf("[nsis %3lu] %-18s", nsis_actions, op);
    if (a) printf(" %s", a);
    if (b) printf(" | %s", b);
    if (c) printf(" | %s", c);
    if (d) printf(" | %s", d);
    putchar('\n');
}

long shim_nsis_set_out_path(const char *path)
{
    record("SetOutPath", z(path), NULL, NULL, NULL);
    return 0;
}

long shim_nsis_mkdir(const char *path)
{
    record("CreateDirectory", z(path), NULL, NULL, NULL);
    return 0;
}

long shim_nsis_rmdir(const char *flags, const char *path)
{
    record(flags && *flags ? "RMDir /r" : "RMDir", z(path), NULL, NULL, NULL);
    return 0;
}

long shim_nsis_delete(const char *path)
{
    record("Delete", z(path), NULL, NULL, NULL);
    return 0;
}

long shim_nsis_file(const char *flags, const char *pattern)
{
    record(flags && *flags ? "File /r" : "File", z(pattern), NULL, NULL, NULL);
    if (strstr(z(pattern), "\\*")) {
        printf("            payload not embedded: build output is absent "
               "from archive/\n");
    }
    return 0;
}

long shim_nsis_ini_write(const char *path, const char *section,
                         const char *key, const char *value)
{
    record("WriteIniStr", z(path), z(section), z(key), z(value));
    return 0;
}

long shim_nsis_reg_write(const char *root, const char *key,
                         const char *name, const char *value)
{
    record("WriteRegStr", z(root), z(key), z(name), z(value));
    return 0;
}

long shim_nsis_reg_delete_key(const char *root, const char *key)
{
    record("DeleteRegKey", z(root), z(key), NULL, NULL);
    return 0;
}

long shim_nsis_shortcut(const char *link, const char *target)
{
    record("CreateShortCut", z(link), z(target), NULL, NULL);
    return 0;
}

long shim_nsis_write_uninstaller(const char *path)
{
    record("WriteUninstaller", z(path), NULL, NULL, NULL);
    return 0;
}

long shim_nsis_set_attrs(const char *path, const char *attrs)
{
    record("SetFileAttributes", z(path), z(attrs), NULL, NULL);
    return 0;
}

long shim_nsis_set_overwrite(const char *mode)
{
    record("SetOverwrite", z(mode), NULL, NULL, NULL);
    return 0;
}

long shim_nsis_set_autoclose(const char *mode)
{
    record("SetAutoClose", z(mode), NULL, NULL, NULL);
    return 0;
}

long shim_nsis_hide_window(void)
{
    record("HideWindow", NULL, NULL, NULL, NULL);
    return 0;
}

long shim_nsis_message_box(const char *flags, const char *text)
{
    record("MessageBox", z(flags), z(text), NULL, NULL);
    printf("            dry run answers IDYES\n");
    return 6; /* IDYES */
}

long shim_nsis_abort(void)
{
    record("Abort", NULL, NULL, NULL, NULL);
    return 1;
}

long shim_nsis_exec(const char *command)
{
    record("nsExec::ExecToLog", z(command), NULL, NULL, NULL);
    return 0;
}

long shim_nsis_system_call(const char *signature)
{
    record("System::Call", z(signature), NULL, NULL, NULL);
    if (strstr(z(signature), "GetSystemWow64Directory")) {
        /* A 64-bit host answers with a non-empty directory. */
        return (long)"C:\\Windows\\SysWOW64";
    }
    return (long)"";
}

long shim_nsis_unimplemented(const char *line)
{
    record("ui-only", z(line), NULL, NULL, NULL);
    return 0;
}

unsigned long shim_nsis_action_count(void)
{
    return nsis_actions;
}
